import{_ as e,o as d,c as s,ak as a}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"Analytics widgets","description":"Every widget of the Analytics page and of analytics dashboards, band by band, with what it shows and whether it follows a test filter, generated from the widget registry.","frontmatter":{"title":"Analytics widgets","description":"Every widget of the Analytics page and of analytics dashboards, band by band, with what it shows and whether it follows a test filter, generated from the widget registry.","lang":"en-US","editLink":false,"head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/analytics-widgets.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/analytics-widgets.html"}],["meta",{"property":"og:title","content":"Analytics widgets | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Every widget of the Analytics page and of analytics dashboards, band by band, with what it shows and whether it follows a test filter, generated from the widget registry."}]]},"headers":[],"relativePath":"reference/analytics-widgets.md","filePath":"reference/analytics-widgets.md","lastUpdated":null}'),r={name:"reference/analytics-widgets.md"};function o(n,t,i,c,h,l){return d(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="analytics-widgets" tabindex="-1">Analytics widgets <a class="header-anchor" href="#analytics-widgets" aria-label="Permalink to &quot;Analytics widgets&quot;">​</a></h1><p>Every widget the <a href="/features/analytics.html">Analytics</a> page shows and an <a href="/features/dashboards.html">analytics dashboard</a> can place, listed under its home band: the band of the Analytics page it belongs to, and the group the widget picker lists it under. Each widget follows the scope bar. One that does not follow a <strong>test filter</strong> (a selection, test tags or browsers) says so under its title when a test filter is set. The numbers the widgets show are defined once, in <a href="/reference/metrics.html">Metrics</a>.</p><h2 id="where-things-stand" tabindex="-1">Where things stand <a class="header-anchor" href="#where-things-stand" aria-label="Permalink to &quot;Where things stand&quot;">​</a></h2><p>The state of every project right now.</p><table tabindex="0"><thead><tr><th>Widget</th><th>What it shows</th><th>Follows a test filter</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Headline numbers</strong> <code>stats</code></td><td>A row of numbers from the metric catalog, each with its change.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>Verdict</strong> <code>verdict</code></td><td>One sentence on how things stand, built by rules from the numbers.</td><td>yes</td><td></td></tr><tr><td><strong>Narrative</strong> <code>narrative</code></td><td>Three paragraphs written by the configured AI model from the report’s numbers, in scheduled quality reports that turn it on; the rule-based verdict elsewhere.</td><td>yes</td><td></td></tr><tr><td><strong>Portfolio health</strong> <code>portfolio</code></td><td>Every project: pass rate and its change, flaky volume, open failure causes, latest run.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>Insights</strong> <code>insights</code></td><td>Findings over the period, ranked by severity.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>Pass rate heatmap</strong> <code>pass-rate-heatmap</code></td><td>Pass rate per project and day.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>Note</strong> <code>text</code></td><td>A note in Markdown.</td><td>no</td><td></td></tr></tbody></table><h2 id="where-the-pain-is" tabindex="-1">Where the pain is <a class="header-anchor" href="#where-the-pain-is" aria-label="Permalink to &quot;Where the pain is&quot;">​</a></h2><p>What is costing you the most time and attention.</p><table tabindex="0"><thead><tr><th>Widget</th><th>What it shows</th><th>Follows a test filter</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Fixes and triage</strong> <code>progress</code></td><td>Failure causes fixed, assigned and ticketed, quarantine releases, auto-heal pull requests.</td><td>no</td><td></td></tr><tr><td><strong>Hand-back outcomes</strong> <code>handbacks</code></td><td>What became of what Piwi handed back: locator heals, auto-heal pull requests, AI diagnoses, gate verdicts, verified flake fixes.</td><td>no</td><td>on the Analytics page</td></tr><tr><td><strong>Risks</strong> <code>risks</code></td><td>Missed targets, metrics moving the wrong way, failing projects, old failure causes, quarantine debt.</td><td>no</td><td></td></tr><tr><td><strong>Failure clusters</strong> <code>cluster-landscape</code></td><td>The biggest and oldest open failure clusters.</td><td>no</td><td>on the Analytics page</td></tr><tr><td><strong>Flakiest tests</strong> <code>flaky-leaderboard</code></td><td>The flakiest tests across projects, by wasted CI impact.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>Wasted CI time</strong> <code>wasted-time</code></td><td>Minutes spent in waits and in failed attempts, over time and per project.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>Time to fix</strong> <code>time-to-fix</code></td><td>Failure causes opened and fixed, the median time to fix, fixes that held, open causes by age.</td><td>no</td><td>on the Analytics page</td></tr><tr><td><strong>Ownership</strong> <code>ownership</code></td><td>One row per owner: open failure causes, flaky tests, wasted CI minutes, median time to fix.</td><td>no</td><td></td></tr></tbody></table><h2 id="which-way-it-is-going" tabindex="-1">Which way it is going <a class="header-anchor" href="#which-way-it-is-going" aria-label="Permalink to &quot;Which way it is going&quot;">​</a></h2><p>Movement over the selected period.</p><table tabindex="0"><thead><tr><th>Widget</th><th>What it shows</th><th>Follows a test filter</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Metric</strong> <code>metric</code></td><td>One metric as a number, a line, bars, a table or a heatmap, optionally broken down.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>Regression velocity</strong> <code>regression-velocity</code></td><td>New regressions and newly flaky tests per bucket.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>CI time</strong> <code>ci-time-trend</code></td><td>Minutes of CI the runs consumed, over time.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>Suite growth</strong> <code>suite-growth</code></td><td>How many tests the suite has over time, and the share skipped or not run.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>Flaky debt</strong> <code>flaky-debt</code></td><td>Flaky occurrences per run, distinct flaky tests and the quarantine, over time.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>Timeline markers</strong> <code>markers</code></td><td>The timeline markers of the period: releases, deploys, incidents.</td><td>no</td><td></td></tr><tr><td><strong>Performance trend</strong> <code>performance-trend</code></td><td>Run and test durations of one project over the period.</td><td>no</td><td>one project in scope</td></tr></tbody></table><h2 id="detail" tabindex="-1">Detail <a class="header-anchor" href="#detail" aria-label="Permalink to &quot;Detail&quot;">​</a></h2><p>Breakdowns to reach for once you know what you are chasing.</p><table tabindex="0"><thead><tr><th>Widget</th><th>What it shows</th><th>Follows a test filter</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Browser matrix</strong> <code>browser-matrix</code></td><td>Pass rate per project and browser.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>Slow endpoints</strong> <code>slow-endpoints</code></td><td>Backend calls captured during tests, by latency.</td><td>yes</td><td>on the Analytics page</td></tr><tr><td><strong>Environment comparison</strong> <code>environment-comparison</code></td><td>Pass rate and run success per environment, side by side and over time.</td><td>yes</td><td></td></tr><tr><td><strong>Movers</strong> <code>movers</code></td><td>Tests that became flaky, stopped being flaky, or got slower or faster by more than 25 %.</td><td>yes</td><td></td></tr><tr><td><strong>Scenario gaps</strong> <code>scenario-gaps</code></td><td>Open Test Map gaps by class and feature, gaps closed, accepted but unwritten.</td><td>no</td><td>hidden where the <a href="/features/scenario-gaps.html">Test Map</a> is declined</td></tr><tr><td><strong>New scenario gaps</strong> <code>new-gaps</code></td><td>The top new scenario gaps of each project in the period.</td><td>no</td><td>hidden where the <a href="/features/scenario-gaps.html">Test Map</a> is declined</td></tr><tr><td><strong>List</strong> <code>list</code></td><td>The latest runs, open failure causes, flakiest tests or open scenario gaps.</td><td>no</td><td></td></tr><tr><td><strong>Spec health</strong> <code>spec-health</code></td><td>Pass and flaky rates per spec directory of one project.</td><td>no</td><td>one project in scope</td></tr><tr><td><strong>Slowest tests</strong> <code>slow-tests</code></td><td>The slowest tests of one project’s recent runs.</td><td>no</td><td>one project in scope</td></tr><tr><td><strong>Timeout opportunities</strong> <code>timeout-opportunities</code></td><td>Tests whose timeout is far above their real duration, in one project.</td><td>no</td><td>one project in scope</td></tr><tr><td><strong>Selection health</strong> <code>selection-health</code></td><td>How one project’s selections resolve, and the tests none selects.</td><td>no</td><td>one project in scope</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/analytics.html">Analytics</a>: the scope, periods, targets and chart export</li><li><a href="/features/dashboards.html">Dashboards</a>: arranging these widgets into analytics dashboards of your own</li><li><a href="/features/quality-reports.html">Quality reports</a>: any analytics dashboard as a document</li><li><a href="/reference/metrics.html">Metrics</a>: what each number counts</li></ul>',16)])])}const y=e(r,[["render",o]]);export{p as __pageData,y as default};
